<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($title??'') ?></title><link rel="stylesheet" href="<?= e(url('assets/css/app.css')) ?>"></head><body><header class="topbar"><a class="brand" href="<?= e(url()) ?>"><?= e($settings['site_title']??'E-pin') ?></a><nav><?php foreach(($categories??[]) as $c): ?><a href="<?= e(url('category/'.rawurlencode($c['slug']))) ?>"><?= e($c['name']) ?></a><?php endforeach; ?><?php if(!empty($_SESSION['user'])): ?><a href="<?= e(url($_SESSION['user']['role']==='admin'?'admin':'account')) ?>">Hesabım</a><a href="<?= e(url('logout')) ?>">Çıkış</a><?php else: ?><a href="<?= e(url('login')) ?>">Giriş</a><?php endif; ?></nav></header><main class="container"><?php if($m=flash('error')): ?><div class="alert"><?= e($m) ?></div><?php endif; ?><?php require APP_ROOT.'/app/views/'.$view.'.php'; ?></main><footer class="footer"><?= e($settings['footer_text']??'') ?></footer></body></html>
